def maximum_good_subarray_sum(nums, k):
    prefix_sum = 0
    # For each value, the minimal prefix sum (sum before the index) over its occurrences
    min_prefix = {}
    max_sum = float('-inf')

    for x in nums:
        # Update max_sum using previously seen starts
        for target in (x - k, x + k):
            if target in min_prefix:
                sub_sum = prefix_sum + x - min_prefix[target]
                if sub_sum > max_sum:
                    max_sum = sub_sum
        # Keep the minimal prefix sum seen before an occurrence of x
        if x not in min_prefix or prefix_sum < min_prefix[x]:
            min_prefix[x] = prefix_sum
        prefix_sum += x
    # If no "good" subarray exists, return 0
    return max_sum if max_sum != float('-inf') else 0
